-- G17: immutable, explainable target-resolution decisions.
create table public.target_resolver_versions(id uuid primary key default gen_random_uuid(),version text unique not null,policy jsonb not null,status text not null check(status in('draft','active','retired')),activated_at timestamptz,created_at timestamptz not null default now(),check((status='active')=(activated_at is not null)));
insert into public.target_resolver_versions(version,policy,status,activated_at) values('1.0.0','{"normal_zone":[0.75,0.85],"normal_center":0.8,"fluency_zone":[0.86,0.96],"stretch_zone":[0.55,0.74],"hard_prerequisite_mastery":0.85,"semantic":"predicted_task_success"}','active',now());
create table public.student_target_decisions(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,resolver_version_id uuid not null references public.target_resolver_versions(id) on delete restrict,learning_goal_id uuid references public.learning_goals(id) on delete set null,package_version_id uuid references public.learning_package_versions(id) on delete set null,state_checksum text not null,input_snapshot jsonb not null,selected_targets jsonb not null,blocked_targets jsonb not null default '[]',difficulty_policy text not null check(difficulty_policy in('normal','fluency','diagnostic_stretch','conservative')),predicted_success_min numeric not null,predicted_success_max numeric not null,confidence text not null check(confidence in('low','medium','high')),explanation jsonb not null,created_at timestamptz not null default now(),check(predicted_success_min between 0 and 1 and predicted_success_max between predicted_success_min and 1));
create unique index target_decision_determinism_idx on public.student_target_decisions(student_id,resolver_version_id,state_checksum);
alter table public.target_resolver_versions enable row level security;alter table public.student_target_decisions enable row level security;create policy resolver_version_read on public.target_resolver_versions for select using(status='active' or public.is_platform_admin());create policy target_decision_read on public.student_target_decisions for select using(public.can_view_student(student_id));grant select on public.target_resolver_versions,public.student_target_decisions to authenticated;
comment on column public.student_target_decisions.predicted_success_min is 'Task success probability, never a learner percentile, mastery threshold, course completion percentage, or forced result.';
